let product = {
  title: $input.first().json.data.data.title,
  link: $input.first().json.data.data.link,
  content: $input.first().json.data.data.content,
  additional_information: "none"
}
if($input.first().json.data.data.woo == 'yep'){
  product.additional_information = $input.first().json.data.data.woo_data;
}
return {
  data: {
    product: product
  },
  imgs: $input.first().json.data.data.imgs
}

return {
  "product": $('Onboarding Data').first().json.data.product ,
  "content_jobs": $('Content Job Data').first().json.data.content_jobs,
  "campaign": $('Content Job Input').first().json.campaign,
  "previous_strategies": $('Get History Data').first().json.strategy_history
}

function enrichStrategies(content, strategy) {
  return {
    content_strategies: strategy.content_strategies.map(strategyItem => {
      const matchedContentJob = content.content_jobs.find(
        contentJob => contentJob.job === strategyItem.content_job
      );

      return {
        ...strategyItem,
        content_job_data: matchedContentJob || null
      };
    })
  };
}
const content = $('Content Job Data').first().json.data;
const strategy = JSON.parse($input.first().json.content.parts[0].text);
return {
  product: $('Onboarding Data').first().json.data.product,
  strategy: enrichStrategies(content, strategy).content_strategies.map(item => item)
}
